          'Positional play (juego de posición) is built around five core elements every player must understand: angles, distance, timing, lines, and situation. In a positional play exercise, perimeter players and interior "joker" players work together to outplay a set number of defenders — each player must actively find and exploit space, stay cognitively engaged, and be technically capable of executing their decisions under pressure.\n\nSpace is the key underlying concept: the more space a player has, the more time they have, and more time allows for better decision-making and execution. As Johan Cruyff put it, as a receiver you need to find open space that lets you receive the ball in good conditions — often it comes down to just one step more or less in your positioning.\n\nAs the number of players in an exercise increases, so does the complexity — players need to continually track their surroundings and their relationships with teammates while applying these same five principles.',
