              'A strong center forward is often used as a target man — jumping for headers, holding the ball up, and laying it off to onrushing midfielders.',
              'This style is especially useful in bad weather, on poor pitches, or against a strong pressing team you don\'t want to try to play through.',
              'The main goal is turning every clearance and long pass into a potential attack, winning second balls and making the game uncomfortable for the opposition.',
