              'When the false nine moves away from the center backs, defenders face a difficult choice: follow them into midfield (leaving space behind) or stay deep and let them turn and create.',
              'At the same time, wingers or attacking midfielders make runs into the gap the false nine has left, so the team still has players attacking the box.',
