        // Explanation adapted from Train Effective (football training app) scanning education content.
        explanation:
          'Scanning is the action of looking around you, analyzing your surroundings, and using that information to decide your next action — all in a matter of 1-2 seconds. It gives you awareness of your teammates and opponents\' positioning to help you make better decisions.\n\nScanning is often the difference between average and outstanding players. Beyond preventing costly mistakes (like a defender not noticing an unmarked striker), it lets you genuinely read the game — recognizing your options before you even have the ball, whether that\'s a pass, a switch of play, a dribble, or simply playing it back to a teammate.\n\nWhen to scan: always scan before you receive the ball, not after it arrives. The moment you see a teammate about to pass to you — as the ball leaves their foot — is when you should take a quick look over your shoulder. Essentially, whenever you\'re not in possession, you should be scanning.\n\nHow often: as much as possible. Arsène Wenger has noted that the very best players scan 6-8 times in just 10 seconds before receiving the ball, compared to just 3-4 times for average players.\n\nHow to train it, in three steps:\n1. Build the habit — most players don\'t fail at scanning because they\'re bad at it, but because they simply aren\'t doing it consistently. Start by practicing scanning every time you receive a pass, with real intention, until it becomes natural.\n2. Get better at processing what you see — at first you might just see a blur of different colored kits; with repetition, you\'ll start actually identifying what\'s happening around you.\n3. Learn how to use the information — once scanning is a habit and you can process what you see, the final step is using it to make smart decisions (control, dribble, shoot, pass). This game intelligence develops by watching professional games (especially players in your position), analyzing decisions and outcomes, and reviewing footage of your own games to learn from your own mistakes.',
